import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import SummaryStep from '../CharacterSheet/SummaryStep'; 
import './GMDashboard.css';

const BOARD_SIZE = 4000; // Devasa sonsuz tuval boyutu

const GMDashboard = () => {
    const navigate = useNavigate();
    const logContainerRef = useRef(null);

    // --- PANEL STATE'LERİ ---
    const [isTopOpen, setIsTopOpen] = useState(true);
    const [isBottomOpen, setIsBottomOpen] = useState(false);
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);
    const [isHudOpen, setIsHudOpen] = useState(true);
    const [isDrawingMenuVisible, setIsDrawingMenuVisible] = useState(false);

    // --- OYUN & ZAR STATE'LERİ ---
    const gameCode = "EPIC2026";
    const [logs, setLogs] = useState([{ id: 1, text: "Campaign Started. Waiting for players...", isHidden: false }]);
    const [diceQty, setDiceQty] = useState(1);
    const [diceType, setDiceType] = useState(20);
    const [isHiddenRoll, setIsHiddenRoll] = useState(false);

    // --- MEDYA & BOARD STATE'LERİ ---
    const [bottomTab, setBottomTab] = useState('maps'); 
    const [maps, setMaps] = useState([]);
    const [images, setImages] = useState([]);
    const [activeMapUrl, setActiveMapUrl] = useState(null); // KRAL: Tek gerçek harita değişkeni budur
    const fileInputRef = useRef(null);
    const objectUrlsRef = useRef([]); 

    // Tahta Konum ve Ölçek
    const [board, setBoard] = useState({ 
        x: - (BOARD_SIZE - window.innerWidth) / 2, 
        y: - (BOARD_SIZE - window.innerHeight) / 2, 
        scale: 1, rotation: 0 
    });

    const [isCanvasLocked, setIsCanvasLocked] = useState(false);
    const [isDragging, setIsDragging] = useState(false);
    const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

    // --- ÇİZİM ARAÇLARI ---
    const [activeTool, setActiveTool] = useState('cursor'); 
    const [drawingColor, setDrawingColor] = useState('#ff4d4d');
    const mainCanvasRef = useRef(null);
    const overlayCanvasRef = useRef(null);
    const isDrawingRef = useRef(false);
    const startPosRef = useRef({ x: 0, y: 0 });

    // --- GRID & TOKEN STATE'LERİ ---
    const [grid, setGrid] = useState({ isVisible: true, type: 'square', size: 60, rotation: 0, opacity: 0.3 });
    const [tokens, setTokens] = useState([]);
    const [draggingTokenId, setDraggingTokenId] = useState(null); 
    const draggedTokenRef = useRef(null); 
    const [tokenModal, setTokenModal] = useState({ isOpen: false, mode: 'create', data: { id: null, name: '', color: 'blue', size: 1, hp: '', maxHp: '', ac: '', speed: '', init: '' } });

    // --- OYUNCU (MOCK DATA) ---
    const [players, setPlayers] = useState([
        { id: 'p1', name: 'Elandor', charClass: 'Rogue', level: 4, species: 'Elf', playerName: 'Ahmet', stats: { Strength: 10, Dexterity: 18, Constitution: 12, Intelligence: 14, Wisdom: 10, Charisma: 14 }, proficiencies: { 'Dexterity-Stealth': true }, armorClass: 15, currentHp: 28, maxHp: 32, speed: 30, weapons: [{ id: 1, name: 'Rapier', damageDice: '1d8' }], spellSlots: { 1: { max: 0, used: 0 } }, spells: [], currency: { cp: 0, sp: 5, ep: 0, gp: 120, pp: 0 }, inventory: [], traits: { personality: 'Shadows are friends.' }, portrait: null }
    ]);
    const [selectedPlayer, setSelectedPlayer] = useState(null);
    const calculateModifier = (score) => Math.floor((score - 10) / 2);

    useEffect(() => {
        return () => objectUrlsRef.current.forEach(url => URL.revokeObjectURL(url));
    }, []);

    useEffect(() => {
        if (isHudOpen && logContainerRef.current) logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
    }, [logs, isHudOpen]);

    // --- EVRENSEL SÜRÜKLEME ---
    const handleGlobalMouseMove = (e) => {
        if (draggedTokenRef.current) {
            const { startX, startY, initialX, initialY, element } = draggedTokenRef.current;
            const newX = initialX + (e.clientX - startX) / board.scale;
            const newY = initialY + (e.clientY - startY) / board.scale;
            element.style.left = `${newX}px`;
            element.style.top = `${newY}px`;
        } else if (isDragging && !isCanvasLocked && activeTool === 'cursor') {
            setBoard(prev => ({ ...prev, x: e.clientX - dragStart.x, y: e.clientY - dragStart.y }));
        }
    };

    const handleGlobalMouseUp = () => { 
        setIsDragging(false); 
        if (draggedTokenRef.current) {
            const { id, startX, startY, initialX, initialY } = draggedTokenRef.current;
            const newX = initialX + (startX - e.clientX) / board.scale; // (Mantık düzeltildi)
            setTokens(prev => prev.map(t => t.id === id ? { ...t, x: initialX + (e.clientX - startX) / board.scale, y: initialY + (e.clientY - startY) / board.scale } : t));
            draggedTokenRef.current = null;
            setDraggingTokenId(null);
        }
    };

    const handleBoardMouseDown = (e) => {
        if (activeTool === 'cursor' && !isCanvasLocked) {
            setIsDragging(true);
            setDragStart({ x: e.clientX - board.x, y: e.clientY - board.y });
            return;
        }
        if (activeTool === 'cursor') return;

        e.stopPropagation();
        isDrawingRef.current = true;
        const pos = { x: e.nativeEvent.offsetX, y: e.nativeEvent.offsetY };
        startPosRef.current = pos;

        if (['marker', 'eraser', 'laser'].includes(activeTool)) {
            const ctx = activeTool === 'laser' ? overlayCanvasRef.current.getContext('2d') : mainCanvasRef.current.getContext('2d');
            ctx.beginPath(); ctx.moveTo(pos.x, pos.y);
            ctx.strokeStyle = activeTool === 'eraser' ? 'rgba(0,0,0,1)' : drawingColor;
            ctx.lineWidth = activeTool === 'eraser' ? 40 : 6; 
            ctx.lineCap = 'round'; ctx.lineJoin = 'round';
            ctx.globalCompositeOperation = activeTool === 'eraser' ? 'destination-out' : 'source-over';
        }
    };

    const handleBoardMouseMove = (e) => {
        if (!isDrawingRef.current || activeTool === 'cursor') return;
        const pos = { x: e.nativeEvent.offsetX, y: e.nativeEvent.offsetY };
        const ctxMain = mainCanvasRef.current?.getContext('2d');
        const ctxOverlay = overlayCanvasRef.current?.getContext('2d');

        if (['marker', 'eraser'].includes(activeTool)) {
            ctxMain.lineTo(pos.x, pos.y); ctxMain.stroke();
        } else if (activeTool === 'laser') {
            ctxOverlay.lineTo(pos.x, pos.y); ctxOverlay.stroke();
        } else if (['line', 'circle', 'cone'].includes(activeTool)) {
            ctxOverlay.clearRect(0, 0, BOARD_SIZE, BOARD_SIZE);
            ctxOverlay.beginPath(); ctxOverlay.strokeStyle = drawingColor; ctxOverlay.lineWidth = 4; ctxOverlay.fillStyle = drawingColor + '40'; 
            const dx = pos.x - startPosRef.current.x; const dy = pos.y - startPosRef.current.y;
            const distancePx = Math.sqrt(dx*dx + dy*dy);
            const distanceFt = ((distancePx / grid.size) * 5).toFixed(0); 

            if (activeTool === 'line') {
                ctxOverlay.moveTo(startPosRef.current.x, startPosRef.current.y); ctxOverlay.lineTo(pos.x, pos.y); ctxOverlay.stroke();
                ctxOverlay.fillStyle = '#fff'; ctxOverlay.font = 'bold 28px "Exo 2"'; ctxOverlay.fillText(`${distanceFt} ft`, pos.x + 15, pos.y + 15);
            } else if (activeTool === 'circle') {
                ctxOverlay.arc(startPosRef.current.x, startPosRef.current.y, distancePx, 0, Math.PI * 2); ctxOverlay.stroke(); ctxOverlay.fill();
                ctxOverlay.fillStyle = '#fff'; ctxOverlay.font = 'bold 28px "Exo 2"'; ctxOverlay.fillText(`Rad: ${distanceFt} ft`, pos.x + 15, pos.y + 15);
            } else if (activeTool === 'cone') {
                const angle = Math.atan2(dy, dx); const coneAngle = Math.PI / 6; 
                ctxOverlay.moveTo(startPosRef.current.x, startPosRef.current.y);
                ctxOverlay.lineTo(startPosRef.current.x + Math.cos(angle - coneAngle) * distancePx, startPosRef.current.y + Math.sin(angle - coneAngle) * distancePx);
                ctxOverlay.arc(startPosRef.current.x, startPosRef.current.y, distancePx, angle - coneAngle, angle + coneAngle);
                ctxOverlay.lineTo(startPosRef.current.x, startPosRef.current.y); ctxOverlay.stroke(); ctxOverlay.fill();
                ctxOverlay.fillStyle = '#fff'; ctxOverlay.font = 'bold 28px "Exo 2"'; ctxOverlay.fillText(`${distanceFt} ft`, pos.x + 15, pos.y + 15);
            }
        }
    };

    const handleBoardMouseUp = () => {
        isDrawingRef.current = false;
        if (['laser', 'line', 'circle', 'cone'].includes(activeTool)) {
            setTimeout(() => { if (overlayCanvasRef.current) overlayCanvasRef.current.getContext('2d').clearRect(0, 0, BOARD_SIZE, BOARD_SIZE); }, 1500);
        }
    };

    const handleTokenMouseDown = (e, token) => {
        if (activeTool !== 'cursor') return; 
        e.stopPropagation();
        setDraggingTokenId(token.id);
        draggedTokenRef.current = { id: token.id, startX: e.clientX, startY: e.clientY, initialX: token.x, initialY: token.y, element: e.currentTarget };
    };

    const openTokenModal = (mode, tokenData = null) => { setTokenModal({ isOpen: true, mode, data: tokenData ? { ...tokenData } : { id: null, name: '', color: 'blue', size: 1, hp: '', maxHp: '', ac: '', speed: '', init: '' } }); };
    const closeTokenModal = () => setTokenModal({ isOpen: false, mode: 'create', data: {} });
    const saveToken = () => {
        if (tokenModal.mode === 'create') setTokens(prev => [...prev, { ...tokenModal.data, id: Date.now(), x: BOARD_SIZE / 2, y: BOARD_SIZE / 2 }]);
        else setTokens(prev => prev.map(t => t.id === tokenModal.data.id ? { ...tokenModal.data, x: t.x, y: t.y } : t));
        closeTokenModal();
    };
    const removeToken = () => { setTokens(prev => prev.filter(t => t.id !== tokenModal.data.id)); closeTokenModal(); };
    const handleAddQuickToken = (color) => { setTokens(prev => [...prev, { id: Date.now(), color, size: 1, name: '', hp: '', maxHp: '', ac: '', speed: '', init: '', x: BOARD_SIZE / 2, y: BOARD_SIZE / 2 }]); };

    const handleFileUpload = (e) => {
        const file = e.target.files[0]; if (!file) return;
        const url = URL.createObjectURL(file); objectUrlsRef.current.push(url); 
        const newItem = { id: Date.now(), name: file.name, url };
        if (bottomTab === 'maps') setMaps(prev => [...prev, newItem]); else setImages(prev => [...prev, newItem]);
        e.target.value = null; 
    };

    const handleMediaDelete = (id, e) => {
        e.stopPropagation(); if(!window.confirm("Silinsin mi?")) return;
        const item = maps.find(m => m.id === id) || images.find(img => img.id === id);
        if (item) URL.revokeObjectURL(item.url);
        if (bottomTab === 'maps') setMaps(prev => prev.filter(m => m.id !== id)); else setImages(prev => prev.filter(img => img.id !== id));
        if(activeMapUrl === item?.url) setActiveMapUrl(null);
    };

    const handleShowOnCanvas = (item) => { 
        setActiveMapUrl(item.url); 
        setBoard(prev => ({...prev, scale: 1, rotation: 0, x: - (BOARD_SIZE - window.innerWidth) / 2, y: - (BOARD_SIZE - window.innerHeight) / 2}));
        setIsCanvasLocked(false); setActiveTool('cursor');
    };

    const handleBoardTransform = (action) => {
        if (isCanvasLocked) return;
        setBoard(prev => {
            let { scale, rotation } = prev;
            if (action === 'zoomIn') scale = Math.min(10, scale + 0.1);
            if (action === 'zoomOut') scale = Math.max(0.1, scale - 0.1);
            if (action === 'rotateLeft') rotation -= 15;
            if (action === 'rotateRight') rotation += 15;
            if (action === 'reset') { scale = 1; rotation = 0; }
            return { ...prev, scale, rotation };
        });
    };

    const handleCopyCode = () => { navigator.clipboard.writeText(gameCode); addLog(`Game Code copied.`, true); };
    const addLog = (text, isHidden = false) => { setLogs(prev => [...prev, { id: Date.now(), text, isHidden }]); };
    const handleRollDice = () => {
        let total = 0; let rolls = [];
        for(let i = 0; i < diceQty; i++) { let r = Math.floor(Math.random() * diceType) + 1; rolls.push(r); total += r; }
        addLog(`GM Rolled ${diceQty}d${diceType} 🎲 [${rolls.join(', ')}] = ${total}`, isHiddenRoll);
        if(!isHudOpen) setIsHudOpen(true);
    };

    return (
        <div className="gm-dashboard-wrapper" onMouseMove={handleGlobalMouseMove} onMouseUp={handleGlobalMouseUp}>

            {/* --- ÇİZİM MENÜSÜ --- */}
            <div className={`drawing-tools-menu ${isSidebarOpen ? 'sidebar-open' : ''} ${isDrawingMenuVisible ? 'visible' : 'tools-hidden'}`}>
                <button type="button" className={`tool-btn ${activeTool === 'cursor' ? 'active' : ''}`} onClick={() => setActiveTool('cursor')}>👆</button>
                <div className="tool-divider"></div>
                <button type="button" className={`tool-btn ${activeTool === 'marker' ? 'active' : ''}`} onClick={() => setActiveTool('marker')}>🖍️</button>
                <button type="button" className={`tool-btn ${activeTool === 'laser' ? 'active' : ''}`} onClick={() => setActiveTool('laser')}>⚡</button>
                <button type="button" className={`tool-btn ${activeTool === 'line' ? 'active' : ''}`} onClick={() => setActiveTool('line')}>📏</button>
                <button type="button" className={`tool-btn ${activeTool === 'circle' ? 'active' : ''}`} onClick={() => setActiveTool('circle')}>⭕</button>
                <button type="button" className={`tool-btn ${activeTool === 'cone' ? 'active' : ''}`} onClick={() => setActiveTool('cone')}>📐</button>
                <button type="button" className={`tool-btn ${activeTool === 'eraser' ? 'active' : ''}`} onClick={() => setActiveTool('eraser')}>🧽</button>
                <input type="color" className="color-picker-tool" value={drawingColor} onChange={(e) => setDrawingColor(e.target.value)} />
                <button type="button" className="tool-btn danger" onClick={handleClearDrawings}>🗑️</button>
            </div>

            {/* --- LAYER 0: MAP & BOARD --- */}
            <div className="layer-map">
                {activeMapUrl ? (
                    <div className="canvas-view-area">
                        <div className="vtt-board-container" style={{ width: BOARD_SIZE, height: BOARD_SIZE, transform: `translate(${board.x}px, ${board.y}px) scale(${board.scale}) rotate(${board.rotation}deg)` }}>
                            {grid.isVisible && (
                                <div className="vtt-grid-layer" style={{ opacity: grid.opacity, transform: `rotate(${grid.rotation}deg)` }}>
                                    <svg width="100%" height="100%"><defs><pattern id="sqGrid" width={grid.size} height={grid.size} patternUnits="userSpaceOnUse"><path d={`M ${grid.size} 0 L 0 0 0 ${grid.size}`} fill="none" stroke="rgba(255,255,255,0.4)" strokeWidth="1"/></pattern></defs><rect width="100%" height="100%" fill="url(#sqGrid)" /></svg>
                                </div>
                            )}
                            <img src={activeMapUrl} alt="Map" className="vtt-map-image" draggable="false" />
                            <canvas ref={mainCanvasRef} width={BOARD_SIZE} height={BOARD_SIZE} className="vtt-drawing-layer" />
                            <canvas ref={overlayCanvasRef} width={BOARD_SIZE} height={BOARD_SIZE} className="vtt-drawing-layer" />

                            {tokens.map(token => (
                                <div key={token.id} className={`map-token color-${token.color} ${draggingTokenId === token.id ? 'dragging' : ''}`} style={{ left: token.x, top: token.y, width: grid.size * token.size * 0.85, height: grid.size * token.size * 0.85, pointerEvents: activeTool === 'cursor' ? 'auto' : 'none' }} onMouseDown={(e) => handleTokenMouseDown(e, token)} onDoubleClick={() => openTokenModal('edit', token)}>
                                    {token.maxHp && (<div className="token-hp-bar"><div className="token-hp-fill" style={{ width: `${(parseFloat(token.hp) / parseFloat(token.maxHp)) * 100}%` }}></div></div>)}
                                    {token.name && <span className="token-name-tag">{token.name}</span>}
                                </div>
                            ))}

                            <div className={`vtt-event-catcher ${activeTool === 'cursor' ? 'cursor-mode' : ''}`} onMouseDown={handleBoardMouseDown} onMouseMove={handleBoardMouseMove} onMouseUp={handleBoardMouseUp} onMouseOut={handleBoardMouseUp} />
                        </div>

                        <div className={`canvas-controls ${isBottomOpen ? 'shifted' : ''}`}>
                            <button type="button" className={`lock-canvas-btn ${isCanvasLocked ? 'locked' : 'unlocked'}`} onClick={() => setIsCanvasLocked(!isCanvasLocked)}>{isCanvasLocked ? '🔒 LOCKED' : '🔓 UNLOCKED'}</button>
                            {!isCanvasLocked && (
                                <div style={{display:'flex', gap:'15px'}}>
                                    <div className="zoom-ctrls"><button type="button" onClick={() => handleBoardTransform('zoomOut')}>[-]</button><span>Zoom: {board.scale.toFixed(1)}x</span><button type="button" onClick={() => handleBoardTransform('zoomIn')}>[+]</button></div>
                                    <button type="button" className="reset-canvas-btn" onClick={() => handleBoardTransform('reset')}>↩ RESET</button>
                                </div>
                            )}
                        </div>
                    </div>
                ) : (
                    <div className="canvas-placeholder-text"><span>🗺️ BATTLEMAP CANVAS</span><br/>Select a map from the bottom menu</div>
                )}
            </div>

            {/* --- DIGER MENULER (AYNI) --- */}
            {selectedPlayer && (
                <div className={`layer-character-sheet fade-in ${!isSidebarOpen ? 'sidebar-closed' : ''}`}>
                    <div className="sheet-overlay-header"><h2>{selectedPlayer.name}'s Sheet</h2><button type="button" className="close-sheet-btn" onClick={() => setSelectedPlayer(null)}>✕ CLOSE</button></div>
                    <div className="sheet-scroll-area"><SummaryStep character={selectedPlayer} calculateModifier={calculateModifier} /></div>
                </div>
            )}

            <div className={`layer-sidebar ${isSidebarOpen ? 'open' : 'closed'}`}>
                <button type="button" className="sidebar-toggle-btn" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>{isSidebarOpen ? '◀' : '▶'}</button>
                <div className="sidebar-content">
                    <h3 className="sidebar-title">PARTY MEMBERS</h3>
                    <div className="player-list">
                        {players.map(p => (
                            <div key={p.id} className={`player-card ${selectedPlayer?.id === p.id ? 'active' : ''}`} onClick={() => setSelectedPlayer(p)}>
                                <div className="p-card-header"><strong>{p.name}</strong><span className="p-hp-tag">HP: {p.currentHp}/{p.maxHp}</span></div>
                                <div className="p-card-sub">Lvl {p.level} {p.charClass}</div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            <div className={`layer-top-menu ${isTopOpen ? 'open' : 'closed'}`}>
                <div className="top-menu-content">
                    <div className="top-left">
                        <button type="button" className="exit-btn" onClick={() => navigate('/host-game')}>🚪 EXIT</button>
                        <div className="game-code-box" onClick={handleCopyCode}>JOIN CODE: <span className="highlight-code">{gameCode}</span></div>
                    </div>
                    <button type="button" className="action-btn combat-btn" onClick={() => addLog("⚔️ COMBAT INITIATED!")}>START COMBAT</button>
                </div>
                <div className="menu-handle top-handle" onClick={() => setIsTopOpen(!isTopOpen)}>{isTopOpen ? '▲' : '▼'}</div>
            </div>

            <div className={`layer-bottom-menu ${isBottomOpen ? 'open' : 'closed'}`}>
                <div className="menu-handle bottom-handle" onClick={() => setIsBottomOpen(!isBottomOpen)}>{isBottomOpen ? '▼' : '▲'} MEDIA & GRID</div>
                <div className="bottom-menu-content">
                    <input type="file" accept="image/*" ref={fileInputRef} style={{ display: 'none' }} onChange={handleFileUpload} />
                    <div className="media-tabs-column">
                        <div className="tab-buttons">
                            <button type="button" className={`tab-btn ${bottomTab === 'maps' ? 'active' : ''}`} onClick={() => setBottomTab('maps')}>🗺️ MAPS</button>
                            <button type="button" className={`tab-btn ${bottomTab === 'images' ? 'active' : ''}`} onClick={() => setBottomTab('images')}>🖼️ IMAGES</button>
                        </div>
                        <button type="button" className={`tab-btn ${bottomTab === 'grid' ? 'active' : ''}`} onClick={() => setBottomTab('grid')}>📐 GRID & TOKENS</button>
                        <button type="button" className={`tab-btn ${isDrawingMenuVisible ? 'active' : ''}`} onClick={() => setIsDrawingMenuVisible(!isDrawingMenuVisible)}>🎨 DRAWING TOOLS</button>
                        {(bottomTab === 'maps' || bottomTab === 'images') && <button type="button" className="upload-media-btn" onClick={() => fileInputRef.current?.click()}>+ UPLOAD</button>}
                    </div>
                    <div className="media-gallery">
                        {bottomTab === 'grid' ? (
                            <div className="grid-token-panel">
                                <div className="grid-settings-box">
                                    <h4>GRID SETTINGS</h4>
                                    <div className="grid-controls-row">
                                        <label className="checkbox-label">Show: <input type="checkbox" checked={grid.isVisible} onChange={(e) => setGrid({...grid, isVisible: e.target.checked})} /></label>
                                        <label>Size: <input type="range" min="20" max="150" value={grid.size} onChange={(e) => setGrid({...grid, size: parseInt(e.target.value)})} /></label>
                                    </div>
                                </div>
                                <div className="token-spawner-box">
                                    <h4>SPAWN TOKENS</h4>
                                    <div className="token-buttons-row">
                                        <button type="button" className="token-btn red" onClick={() => handleAddQuickToken('red')}></button>
                                        <button type="button" className="token-btn blue" onClick={() => handleAddQuickToken('blue')}></button>
                                        <button type="button" className="custom-token-btn" onClick={() => openTokenModal('create')}>+ CUSTOM</button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            (bottomTab === 'maps' ? maps : images).map(item => (
                                <div className="media-card" key={item.id}>
                                    <button type="button" className="delete-media-btn" onClick={(e) => handleMediaDelete(item.id, e)}>🗑️</button>
                                    <img src={item.url} alt={item.name} />
                                    <button type="button" className="show-canvas-btn" onClick={() => handleShowOnCanvas(item)}>DISPLAY</button>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>

            <button type="button" className={`hud-fab-btn ${!isHudOpen ? 'visible' : 'hidden'} ${isBottomOpen ? 'shifted' : ''}`} onClick={() => setIsHudOpen(true)}>🎲 DICE & LOGS</button>
            <div className={`layer-hud ${isHudOpen ? 'visible' : 'hidden'} ${isBottomOpen ? 'shifted' : ''}`}>
                <div className="hud-header-bar"><span>ACTION CENTER</span><button type="button" className="hud-close-btn" onClick={() => setIsHudOpen(false)}>✕</button></div>
                <div className="hud-content">
                    <div className="dice-panel">
                        <div className="dice-controls"><input type="number" min="1" max="99" value={diceQty} onChange={(e) => setDiceQty(e.target.value)} /><span>d20</span></div>
                        <button type="button" className="roll-btn" onClick={handleRollDice}>ROLL 🎲</button>
                    </div>
                    <div className="log-panel"><div className="log-messages" ref={logContainerRef}>{logs.map(log => (<div key={log.id} className="log-entry">{log.text}</div>))}</div></div>
                </div>
            </div>

            {/* --- TOKEN MODAL --- */}
            {tokenModal.isOpen && (
                <div className="modal-overlay" style={{zIndex: 1000}}>
                    <div className="modal-content" style={{maxWidth: '400px'}}>
                        <h2>{tokenModal.mode === 'create' ? 'Create Token' : 'Edit Token'}</h2>
                        <div className="modal-input-row">
                            <label>Name: <input type="text" value={tokenModal.data.name} onChange={(e) => setTokenModal({...tokenModal, data: {...tokenModal.data, name: e.target.value}})} /></label>
                            <label>Size: <select value={tokenModal.data.size} onChange={(e) => setTokenModal({...tokenModal, data: {...tokenModal.data, size: parseFloat(e.target.value)}})}><option value={1}>1x1</option><option value={2}>2x2</option></select></label>
                        </div>
                        <div className="modal-input-row">
                            <label>HP: <input type="number" value={tokenModal.data.hp} onChange={(e) => setTokenModal({...tokenModal, data: {...tokenModal.data, hp: e.target.value}})} /></label>
                            <label>Max HP: <input type="number" value={tokenModal.data.maxHp} onChange={(e) => setTokenModal({...tokenModal, data: {...tokenModal.data, maxHp: e.target.value}})} /></label>
                        </div>
                        <div className="modal-actions">
                            <button type="button" onClick={closeTokenModal}>CANCEL</button>
                            <button type="button" onClick={saveToken}>SAVE</button>
                            {tokenModal.mode === 'edit' && <button type="button" onClick={removeToken}>DELETE</button>}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GMDashboard;
